from __future__ import annotations

import json
import pathlib
from typing import Optional

from .schema import Note

# Resolved at import time relative to this file's package root.
_NOTES_DATA = pathlib.Path(__file__).parent.parent / "notes_data"


def _data_dir() -> pathlib.Path:
    _NOTES_DATA.mkdir(parents=True, exist_ok=True)
    return _NOTES_DATA


def _next_id() -> int:
    existing = [
        int(p.stem)
        for p in _data_dir().glob("*.json")
        if p.stem.isdigit()
    ]
    return max(existing, default=0) + 1


def save_note(note: Note) -> None:
    path = _data_dir() / f"{note.id}.json"
    path.write_text(note.to_json(), encoding="utf-8")


def load_note(note_id: int) -> Optional[Note]:
    path = _data_dir() / f"{note_id}.json"
    if not path.exists():
        return None
    data = json.loads(path.read_text(encoding="utf-8"))
    return Note.from_dict(data)


def list_notes() -> list[Note]:
    notes = []
    for p in sorted(_data_dir().glob("*.json"), key=lambda x: int(x.stem) if x.stem.isdigit() else 0):
        if p.stem.isdigit():
            data = json.loads(p.read_text(encoding="utf-8"))
            notes.append(Note.from_dict(data))
    return notes


def create_note(title: str, tags: list[str], body: str, citation: Optional[str]) -> Note:
    note = Note(
        id=_next_id(),
        title=title,
        tags=list(tags),
        body=body,
        citation=citation or None,
    )
    save_note(note)
    return note

